    Bug 2019253 - Fix state bleed during --verify runs of browser_offlineSettings.js. r=darktrojan


    Folder offline flags were retaining their modified state between test
    iterations, causing failures during repeated runs. This is fixed by explicitly
    setting and clearing all relevant folder flags during `add_setup`. This
    guarantees the state is correct before any assertions run, flattening any dirty
    cache left over from previous iterations.

    Differential Revision: https://phabricator.services.mozilla.com/D286555

diff --git a/mail/test/browser/account/browser_offlineSettings.js b/mail/test/browser/account/browser_offlineSettings.js
index da5168aaa6d..6cbdf9cb8d6 100644
--- a/mail/test/browser/account/browser_offlineSettings.js
+++ b/mail/test/browser/account/browser_offlineSettings.js
@@ -73,7 +73,13 @@ add_setup(async () => {
     .getChildNamed("offline.second")
     .setFlag(Ci.nsMsgFolderFlags.Offline);
   nntpRootFolder.createSubfolder("offline.third", null);
+  nntpRootFolder
+    .getChildNamed("offline.third")
+    .clearFlag(Ci.nsMsgFolderFlags.Offline);
   nntpRootFolder.createSubfolder("offline.third.fourth", null);
+  nntpRootFolder
+    .getChildNamed("offline.third.fourth")
+    .clearFlag(Ci.nsMsgFolderFlags.Offline);

   // Set up IMAP account.

@@ -96,6 +102,10 @@ add_setup(async () => {
       imapRootFolder.getChildNamed("third").numSubFolders == 1,
     "waiting for IMAP folders to sync"
